import React, { PropsWithChildren } from 'react';

import { XYChartVisibleAxesContext } from '../context/axes/XYChartVisibleAxes.context.js';
import { getScaleByAxisId } from '../functions/get-scale-by-axis-id.js';
import { getVisibleAxes } from '../functions/get-visible-axes.js';
import { useAxesConfig } from '../hooks/useAxesConfig.js';
import { useXYChartXScales } from '../hooks/useXYChartXScales.js';
import { XYChartVisibleAxesScales } from '../types/xy-chart.js';

export function XYChartVisibleAxesProvider({ children }: PropsWithChildren) {
  const axes = useAxesConfig();
  const xScales = useXYChartXScales();

  const visibleAxesConfig = getVisibleAxes(axes);
  const bottomScale = visibleAxesConfig.bottom
    ? getScaleByAxisId(visibleAxesConfig.bottom.id, xScales)
    : undefined;
  const scales: XYChartVisibleAxesScales = { bottom: bottomScale };

  return (
    <XYChartVisibleAxesContext.Provider
      value={{ config: visibleAxesConfig, scales }}
    >
      {children}
    </XYChartVisibleAxesContext.Provider>
  );
}
